        /// <summary>
        /// Render Report header
        /// </summary>
        /// <param name="headerTemplate"></param>
        private void RenderReportHeader(Result_Template template)
        {
            switch (this.bettype)
            {
                case (int)Sunplus.Agent.Model.BL.Definitions.BetType.Mix_Parlay:
                    this.tpl.ResultTitle.Title = this.tpl.Title = Resources.Lang.lblMixParlay;
                    break;
                case (int)Sunplus.Agent.Model.BL.Definitions.BetType.Combine_Mix_Parlay:
                    this.tpl.ResultTitle.Title = this.tpl.Title = Resources.Lang.lblSystemParlay;
                    break;
                default:
                    template.ResultTitle.Title = template.Title = Resources.Lang.result;
                    break;
            }

            template.ResultTitle.NormalResult = Resources.Lang.lblNormal;
            template.ResultTitle.disabledNormal = this.isOutright ? string.Empty : "disabled = 'disabled'";
            template.ResultTitle.disabledNormalClass = this.isOutright ? string.Empty : "btn2";

            template.ResultTitle.OutrightResult = Resources.Lang.lblOutRight;
            template.ResultTitle.disabledOutright = this.isOutright ? "disabled = 'disabled'" : string.Empty;
            template.ResultTitle.disabledOutrightClass = this.isOutright ? "btn2" : string.Empty;

            if (UserPermission.EnableKeno && UserSession.Current.IsShowSportbook && IPHelper.IsWebVpnAccess())
            {
                HttpContext context = HttpContext.Current;
                var sessionTmp = "/(S(" + CurrentUserSession.NetSessionId + "))/";
                string baseUrl = context.Request.ApplicationPath.Equals("/") ? sessionTmp : (context.Request.ApplicationPath + sessionTmp);

                //string url = baseUrl + "game/keno/kenoresult/index?date=20140311&language=en&customerId=1373389";

                string languageCode = string.Empty;
                switch (CurrentUserSession.LangKey)
                {
                    case "E": languageCode = "EN";
                        break;
                    case "J": languageCode = "JP";
                        break;
                    case "CT": languageCode = "CH";
                        break;
                    case "CS": languageCode = "CS";
                        break;
                    case "TH": languageCode = "TH";
                        break;
                    case "KO": languageCode = "KO";
                        break;
                    case "VI": languageCode = "VI";
                        break;
                    default:
                        languageCode = "EN";
                        break;
                }

                string url = baseUrl + "game/keno/kenoresult/index?date=" + String.Format("{0:yyyyMMdd}", DateTime.Now) + "&language=" + languageCode.ToLower() + "&customerId=" + _custId;
                template.ResultTitle.KenoTitle.kenoURL = url;
                template.ResultTitle.KenoTitle.KenoResult = Resources.Lang.Keno;
            }
            else
            {
                template.ResultTitle.KenoTitle.Hide();
            }

            template.HeaderRegion.DateRangeSelect.SearchByDateFunction = "Result_SearchByDate()";
            template.HeaderRegion.DateRangeSelect.SearchOneDateFunction = "Result_SearchOneDay(this.value)";

        }

