        /// <summary>
        /// Render report content
        /// </summary>
        /// <param name="template"></param>
        private void RenderReportContent(Result_ExcelContents_Block excelBlock)
        {
            if (this.isOutright)
            {
                this.RenderOutright(excelBlock);
            }
            else
            {
                DataTable reportData = (View as Dictionary<string, DataTable>)["ReportData"];

                // view match result popup
                if (this._matchId > 0)
                {
                    string title = string.Empty;
                    title += string.Join(null, new string[] { "<strong><span class=\"bl_stype\">", Sunplus.Agent.Model.BL.Cache.CacheRef.GetSportName(this._sportId), "</span></strong>", " - ", Sunplus.Agent.Model.BL.Cache.CacheRef.GetLeagueName(this._leagueId) });
                    this.tpl.ResultTitle.Title = this.tpl.Title = title;
                }

                switch (this._sportId)
                {
                    case (int)Sunplus.Agent.Model.BL.Definitions.SportType.Soccer:
                        this.RenderSoccer(reportData, excelBlock);
                        break;
                    case (int)Sunplus.Agent.Model.BL.Definitions.SportType.BasketBall:
                    case (int)Sunplus.Agent.Model.BL.Definitions.SportType.Netball:
                    case (int)Sunplus.Agent.Model.BL.Definitions.SportType.FootBall:
