        /// <param name="FGLG"></param>
        /// <param name="rowBlock"></param>
        private void ShowSoccerFGLGLimitForHtml(string FGLG, Result.ResultSoccer_RowData_Row_Block rowBlock)
        {
            string[] FGLGArray = FGLG.Split(':');
            if (FGLGArray.Length > 1)
            {
                if (string.Compare(FGLGArray[0], "1FL", true) == 0) // first half  
                {
                    ShowSoccerFGLGLimitForHtmlFirstHalf(rowBlock, FGLGArray[1]);
                }
                else
                {
                    if (string.Compare(FGLGArray[0], "FL", true) == 0) // second half
                    {
                        ShowSoccerFGLGLimitForHtmlSecondHalf(rowBlock, FGLGArray[1]);
                    }
                }
            }
        }

