        /// <summary>
        /// Render Soccer result content
        /// </summary>
        /// <param name="dr"></param>
        /// <param name="rowBlock"></param>
        private void RenderSoccerResultScore(DataRow dr, Result.ResultSoccer_RowData_Row_Block rowBlock)
        {
            if (_exportToExcel)
            {
                HideFGLGElementExportExcel(rowBlock);
            }
            else
            {
                this.HideFGLGElement(rowBlock);
            }

            string eventStatus = dr["eventstatus"].ToString();
            if (eventStatus == REFUND)
            {
                RenderSoccerResultScoreRefund(dr, rowBlock);
            }
            else if (eventStatus == REFUND_FT)
            {
                RenderSoccerResultScoreRefundFT(dr, rowBlock);
            }
            else if (eventStatus == REFUND_HT)
            {
                RenderSoccerResultScoreRefundHT(dr, rowBlock);
            }
            else
            {
                RenderSoccerResultScoreCalculate(dr, rowBlock);
            }
        }

        private void RenderSoccerResultScoreCalculate(DataRow dr, Result.ResultSoccer_RowData_Row_Block rowBlock)
        {
            string betStatus = dr["betstatus"].ToString().Trim();
            if (!string.IsNullOrEmpty(betStatus))
            {
                string[] refundArray = betStatus.Split(';');
                switch (refundArray.Length)
                {
                    case 1:
                        //format: FL:x-y or 1FL:x-y
                        this.ShowSoccerFGLGLimit(refundArray[0], rowBlock);
                        break;
                    case 2:
                        //format: 1FL:a-b;FL:x-y
                        this.ShowSoccerFGLGLimit(refundArray[1], rowBlock);
                        this.ShowSoccerFGLGLimit(refundArray[0], rowBlock);
                        break;
                    case 3:
                        this.ShowSoccerFGLGLimit(refundArray[2], rowBlock);
                        this.ShowSoccerFGLGLimit(refundArray[1], rowBlock);
                        break;
                }
            }

            rowBlock.HTHomeScore = dr["hthomescore"].ToString();
            rowBlock.HTAwayScore = dr["htawayscore"].ToString();
            rowBlock.FTHomeScore = dr["finalhomescore"].ToString();
            rowBlock.FTAwayScore = dr["finalawayscore"].ToString();
        }

        private void RenderSoccerResultScoreRefundHT(DataRow dr, Result.ResultSoccer_RowData_Row_Block rowBlock)
        {
            string betStatus = dr["betstatus"].ToString().Trim();
            string[] refundArray = betStatus.Split(';');

            if (refundArray.Length == 2)
            {
                this.ShowSoccerFGLGLimit(refundArray[1], rowBlock);//format: Refund HT;FL:x-y or 1FL:x-y
            }
            else if (refundArray.Length == 3)//format: Refund HT;1FL:a-b;FL:x-y
            {
                this.ShowSoccerFGLGLimit(refundArray[2], rowBlock);
                this.ShowSoccerFGLGLimit(refundArray[1], rowBlock);
            }

            rowBlock.HTHomeScore = NA;
            rowBlock.HTAwayScore = NA;
            rowBlock.FTHomeScore = dr["finalhomescore"].ToString();
            rowBlock.FTAwayScore = dr["finalawayscore"].ToString();
        }

