            {
                this.ShowSoccerFGLGLimit(refundArray[1], rowBlock);//format: Refund FT;FL:x-y or 1FL:x-y
            }
            else if (refundArray.Length == 3)//format: Refund FT;1FL:a-b;FL:x-y
            {
                this.ShowSoccerFGLGLimit(refundArray[2], rowBlock);
                this.ShowSoccerFGLGLimit(refundArray[1], rowBlock);
            }

            rowBlock.HTHomeScore = dr["hthomescore"].ToString();
            rowBlock.HTAwayScore = dr["htawayscore"].ToString();
            rowBlock.FTAwayScore = NA;
            rowBlock.FTHomeScore = NA;
        }

        private void RenderSoccerResultScoreRefund(DataRow dr, Result.ResultSoccer_RowData_Row_Block rowBlock)
        {
            string betStatus = dr["betstatus"].ToString().Trim();
            string[] refundArray = betStatus.Split(';');
            if (refundArray.Length == 2)
            {
                this.ShowSoccerFGLGLimit(refundArray[1], rowBlock);//format: Refund FT;FL:x-y or 1FL:x-y
            }
            else if (refundArray.Length == 3)//format: Refund FT;1FL:a-b;FL:x-y
