            rowBlock.FTHomeScore = NA;
        }

        /// <summary>
        /// For Bet-Radar: Render Penalty Shootout Result in EventStatus column.
        /// </summary>
        /// <param name="dr"></param>
        /// <param name="rowBlock"></param>
        private void RenderSoccerPSEventStatus(DataRow dr, Result.ResultSoccer_RowData_Row_Block rowBlock)
        {
            if (_sportId != (int)Sunplus.Agent.Model.BL.Definitions.SportType.Soccer)
            {
                rowBlock.PenaltyShootout.Hide();
                return;
            }

            string betStatus = dr["betstatus"].ToString().Trim().ToUpperInvariant();
            int index = betStatus.IndexOf("PS:");
            if (index == -1)
            {
                rowBlock.PenaltyShootout.Hide();
                return;
            }

            string psStatus = betStatus.Substring(index, 4);
            rowBlock.PenaltyShootout.Show();
            rowBlock.PenaltyShootout.PSResult = psStatus;
            rowBlock.PenaltyShootout.PSResultTooltip = GetLogResource(psStatus.Replace(':', '_'));
        }

