        /// <summary>
        /// Render tennis result
        /// </summary>
        /// <param name="reportData"></param>
        /// <param name="excelBlock"></param>
        private void RenderTennis(DataTable reportData, DataTable detailData, Result_ExcelContents_Block excelBlock)
        {
            //transform detail table to dictionary
            Dictionary<int, TennisMatchStatistics> matchDetailDict = detailData.AsEnumerable()
                                            .Select(x => new TennisMatchStatistics(x.Field<int>(0), x.Field<string[]>(1), x.Field<string[]>(2), x.Field<string>(3), x.Field<string>(4), x.Field<string>(5), x.Field<string>(6), x.Field<string>(7), x.Field<int>(8), x.Field<bool>(9), x.Field<object>(10)))
                                            .ToDictionary(x => x.MatchId, x => x);


            // Get report rows
            Result.ResultTennis_Template template = new ResultTennis_Template();

            int numRow = reportData.Rows.Count;
            template.TableMain.RowData.Clear();
            if (numRow > 0)
            {
                int currentLeagueId = 0;
                string homeTeamText = string.Empty;
                string awayTeamText = string.Empty;
                int matchId = 0;

                Result.ResultTennis_TableMain_RowData_League_Block leagueBlock = new ResultTennis_TableMain_RowData_League_Block();
                Result.ResultTennis_TableMain_RowData_Row_Block rowBlock = new ResultTennis_TableMain_RowData_Row_Block();
                rowBlock.MatchDetail.DetailTooltip = GetLogResource("detailtooltip");
                //template.SetDetail = null;

                // Do NOT show league block when Pop up the result of matches
                if (this._matchId > 0)
                {
                    leagueBlock.Visible = false;
                }
                //View report from result page - main data, view from betlist page - bettype != SetXGameYWinner (1324)
                if ((this._matchId <= 0 || this.isDetail || this._matchId > 0 && this.bettype != (int)BetType.SetXGameYWinner))
                {
                    this.RenderTennisSet(numRow, currentLeagueId, template, leagueBlock, rowBlock, matchDetailDict, ref matchId, ref awayTeamText, ref homeTeamText, reportData);
                }

                //View report from result page - detail data
                if (this._matchId > 0 && isDetail)
                {
                    RenderTennisSetDetail(matchId, template, matchDetailDict, ref awayTeamText, ref homeTeamText);
                }
                //view from betlist, bettype = SetXGameYWinner (1324)
                else if (!isDetail && this._matchId > 0 && this.bettype == (int)BetType.SetXGameYWinner)
                {
                    RenderTennisGame(this._matchId, template, matchDetailDict, ref awayTeamText, ref homeTeamText, reportData);
                }
                else
                {
                    template.SetDetail.Hide();
                }

                template.TableMain.LimitNotFound.Hide();
            }
            else
            {
                template.TableMain.LimitNotFound.NoInfoRow.NumCols = "10";
                template.SetDetail = null;
            }

            excelBlock.Append(template);
        }

