        private void RenderTennisSet(int numRow, int currentLeagueId, ResultTennis_Template template, ResultTennis_TableMain_RowData_League_Block leagueBlock, ResultTennis_TableMain_RowData_Row_Block rowBlock, Dictionary<int, TennisMatchStatistics> matchDetailDict, ref int matchId, ref string awayTeamText, ref string homeTeamText, DataTable reportData)
        {
            rowBlock.MatchDetail.DetailTooltip = GetLogResource("detailtooltip");
            int numberHideMatch = 0;
            for (int i = 0; i < numRow; i++)
            {
                DataRow dr = reportData.Rows[i];
                matchId = Converter.ToInt(dr["matchid"]);
                int bettype = 0;
                if (dr.Table.Columns.Contains("bettype"))
                {
                    bettype = Converter.ToInt(dr["bettype"], -1);
                }

                if (bettype == (int)BetType.SetXGameYWinner)
                {
                    numberHideMatch++;
                    continue;
                }
                int leagueId = Converter.ToInt(dr["leagueid"]);

                if (currentLeagueId == 0 || currentLeagueId != leagueId)
                {
                    currentLeagueId = leagueId;
                    leagueBlock.LeagueName = CacheRef.GetLeagueName(leagueId);
                    template.TableMain.RowData.Append(leagueBlock);
                }

                rowBlock.ColorClass = i % 2 == 0 ? EVEN_ROW_CLASS : ODD_ROW_CLASS;
                rowBlock.KickOffTime = FormatDateTimeNotSecond(dr["kickofftime"]);

                // Home and away team
                this.BoldTeamByFinalScore(dr, ref homeTeamText, ref awayTeamText);
                rowBlock.Home = homeTeamText;
                rowBlock.Away = awayTeamText;

                string[] homeSet = new string[MAX_TENNIS_SET] { "-", "-", "-", "-", "-" };
                string[] awaySet = new string[MAX_TENNIS_SET] { "-", "-", "-", "-", "-" };
                string betStatus = string.Empty;
                string totalGameHome = "-";
                string totalGameAway = "-";
                string totalSetHome = "-";
                string totalSetAway = "-";

                var matchDetailBetStatusValue = 0;
                bool isStatusDetail = false;
                if (matchDetailDict.ContainsKey(matchId))
                {
                    TennisMatchStatistics matchStat = matchDetailDict[matchId];

                    homeSet = matchStat.SetHomeArr;
                    awaySet = matchStat.SetAwayArr;
                    totalGameHome = matchStat.TotalGameHome;
                    totalGameAway = matchStat.TotalGameAway;
                    totalSetHome = matchStat.TotalSetHome;
                    totalSetAway = matchStat.TotalSetAway;

                    matchDetailBetStatusValue = matchStat.StatusValue;
                    isStatusDetail = matchStat.StatusDetail;
                }

                var eventStatus = Converter.ToString2(dr["eventstatus"]);

                betStatus = this.MapEventStatusString(
                        eventStatus,
                        dr.Table.Columns.Contains("IsPending") ? Converter.ToBool(dr["IsPending"]) : false,
                        dr.Table.Columns.Contains("IsHTCal") ? Converter.ToBool(dr["IsHTCal"]) : false,
                        dr.Table.Columns.Contains("calculate") ? Converter.ToBool(dr["calculate"]) : false);

                rowBlock.S1Away = awaySet[0];
                rowBlock.S2Away = awaySet[1];
                rowBlock.S3Away = awaySet[2];
                rowBlock.S4Away = awaySet[3];
                rowBlock.S5Away = awaySet[4];

                rowBlock.S1Home = homeSet[0];
                rowBlock.S2Home = homeSet[1];
                rowBlock.S3Home = homeSet[2];
                rowBlock.S4Home = homeSet[3];
                rowBlock.S5Home = homeSet[4];

                rowBlock.TotalGameAway = totalGameAway;
                rowBlock.TotalGameHome = totalGameHome;
                rowBlock.TotalSetAway = totalSetAway;
                rowBlock.TotalSetHome = totalSetHome;

                //use main row status
                rowBlock.EventStatus = betStatus;

                if (!isStatusDetail)
                {
                    rowBlock.MatchDetail.Hide();
                }
                else
                {
                    if (this._matchId <= 0)
                    {
                        rowBlock.MatchDetail.matchId = matchId.ToString();
                        rowBlock.MatchDetail.refNo = this.refNo.ToString();
                        rowBlock.MatchDetail.league = leagueId.ToString();
                        rowBlock.MatchDetail.Show();
                    }
                    else
                    {
                        rowBlock.MatchDetail.Hide();
                    }
                }

                template.TableMain.RowData.Append(rowBlock);
            }

            if (numberHideMatch == numRow)
            {
                template.TableMain.Hide();
            }
        }

        private void RenderTennisSetDetail(int matchId, ResultTennis_Template template, Dictionary<int, TennisMatchStatistics> matchDetailDict, ref string awayTeamText, ref string homeTeamText)
        {
            if (matchDetailDict.ContainsKey(matchId))
            {
                int game = 0;
                int line = 0;
                template.SetDetail.Clear();

                //Match detail dictionary by resource Id.
                var resourceDict = matchDetailDict[matchId].SetDetailData;

                var setIndex = string.Empty;
                ResultTennis_SetDetail_TableDetail_Block tableDetailBlock = null;

                for (int i = 1; i <= MAX_TENNIS_SET; i++)
                {
                    //if (!resourceDict.ContainsKey(string.Format("0{0}", i)))
                    //{
                    //    continue;
                    //}

                    var currentGameList = (from x in resourceDict where x.Key.StartsWith(string.Format("0{0}", i)) && x.Key.Length > 2 select x.Key).ToDictionary(x => x, null);

                    if (currentGameList.Count == 0)
                    {
                        continue;
                    }

                    tableDetailBlock = new Fanex.Age.UI.Reports.Result.ResultTennis_SetDetail_TableDetail_Block();
                    List<ResultTennis_SetDetail_TableDetail_DetailHeader_Block> detailHeaders = new List<ResultTennis_SetDetail_TableDetail_DetailHeader_Block>();
                    List<ResultTennis_SetDetail_TableDetail_DetailRow_Block> detailRows = new List<ResultTennis_SetDetail_TableDetail_DetailRow_Block>();

                    detailRows.Add(null);
                    detailHeaders.Add(null);

                    detailRows[0] = tableDetailBlock.DetailRow;
                    detailHeaders[0] = tableDetailBlock.DetailHeader;

                    game = 0;
                    line = 0;

                    detailHeaders[0].TitleNameBlock.Set_X_Game_Result = string.Format("Set {0} Game Result", i);
                    detailRows[0].HomeNameBlock.Home = homeTeamText;
                    detailRows[0].AwayNameBlock.Away = awayTeamText;

                    int maxGame = Converter.ToInt(currentGameList.Keys.Max(), MAX_GAME_PER_RESULT_LINE) % 100;

                    while (game < maxGame)
                    {
                        game++;
                        line = ((game - 1) / MAX_GAME_PER_RESULT_LINE) + 1;

                        setIndex = getSetIndex(i, game);
                        if (detailRows.Count < line)
                        {
                            detailRows.Add(new ResultTennis_SetDetail_TableDetail_DetailRow_Block());
                            detailHeaders.Add(new ResultTennis_SetDetail_TableDetail_DetailHeader_Block());

                            if (line < 3)
                            {
                                detailRows[0].HomeNameBlock.Home += "</br>" + detailRows[0].AwayNameBlock.Away;
                            }

                            detailRows[0].AwayNameBlock.Hide();
                            detailRows[0].HomeNameBlock.mergeNum = (line * 3).ToString();

                            detailRows[line - 1].HomeNameBlock.Hide();
                            detailRows[line - 1].AwayNameBlock.Hide();
                            detailHeaders[line - 1].TitleNameBlock.Hide();
                        }

                        if (resourceDict.ContainsKey(setIndex))
                        {
                            var tennisSetDetail = resourceDict[setIndex];

                            if (line == 1) // <= 13 set
                            {
                                setValueToDataRow(game, detailHeaders[0], detailRows[0], tennisSetDetail.HomeValue, tennisSetDetail.AwayValue, tennisSetDetail.SettlementStatusId);
                            }
                            else // > 13 set, > 1 line
                            {
                                detailRows[line - 1].HomeNameBlock.Home = homeTeamText;
                                detailRows[line - 1].AwayNameBlock.Away = awayTeamText;

                                setValueToDataRow(game, detailHeaders[line - 1], detailRows[line - 1], tennisSetDetail.HomeValue, tennisSetDetail.AwayValue, tennisSetDetail.SettlementStatusId);
                            }
                        }
                        else
                        {
                            setValueToDataRow(game, detailHeaders[line - 1], detailRows[line - 1], " -", " -", 4);
                        }
                    }

                    //change name of left column dont have data, game < 13
                    int endGame = (int)Math.Ceiling((double)game / MAX_GAME_PER_RESULT_LINE) * MAX_GAME_PER_RESULT_LINE;
                    while (game < endGame)
                    {
                        game++;
                        setValueToDataRow(game, detailHeaders[line - 1], detailRows[line - 1], " -", " -", 4);
                    }

                    for (int subRowCount = 1; subRowCount <= detailRows.Count - 1; subRowCount++)
                    {
                        tableDetailBlock.DetailRow.Append(detailHeaders[subRowCount]);
                        tableDetailBlock.DetailRow.Append(detailRows[subRowCount]);
                    }
                    tableDetailBlock.NoData.Hide();

                    template.SetDetail.Append(tableDetailBlock);
                }

                template.SetDetail.Show();
            }
        }

        private void RenderTennisGame(int matchId, ResultTennis_Template template, Dictionary<int, TennisMatchStatistics> matchDetailDict, ref string awayTeamText, ref string homeTeamText, DataTable reportData)
        {
            int game = 0;
