                                setValueToDataRow(game, detailHeaders[line - 1], detailRows[line - 1], tennisSetDetail.HomeValue, tennisSetDetail.AwayValue, tennisSetDetail.SettlementStatusId);
                            }
                        }
                        else
                        {
                            setValueToDataRow(game, detailHeaders[line - 1], detailRows[line - 1], " -", " -", (int)MatchSettlementStatus.Completed);
                        }
                    }

                    //change name of left column dont have data, game < 13
                    int endGame = (int)Math.Ceiling((double)game / MAX_GAME_PER_RESULT_LINE) * MAX_GAME_PER_RESULT_LINE;
                    while (game < endGame)
                    {
                        game++;
                        setValueToDataRow(game, detailHeaders[line - 1], detailRows[line - 1], " -", " -", (int)MatchSettlementStatus.Completed);
                    }

                    for (int subRowCount = 1; subRowCount <= detailRows.Count - 1; subRowCount++)
                    {
                        tableDetailBlock.DetailRow.Append(detailHeaders[subRowCount]);
                        tableDetailBlock.DetailRow.Append(detailRows[subRowCount]);
                    }

                    tableDetailBlock.NoData.Hide();
                    template.SetDetail.Append(tableDetailBlock);
                }

                template.SetDetail.Show();
            }
            else
            {
                template.SetDetail.Clear();
                template.TableMain.Hide();
                template.SetDetail.Show();

                string betIdStr = this.betid.ToString();
                int setName = betIdStr.Length == 5 ? Converter.ToInt(betIdStr.Substring(1, 2)) : 0;
                var tableDetailBlock = new Fanex.Age.UI.Reports.Result.ResultTennis_SetDetail_TableDetail_Block();
                tableDetailBlock.DetailHeader.TitleNameBlock.Set_X_Game_Result = string.Format("Set {0} Game Result", setName > 0 ? setName.ToString() : "-");

                tableDetailBlock.NoData.Clear();
                var _NoInfoRow = new NoInfo_Template();
                _NoInfoRow.NumCols = "14";
                tableDetailBlock.NoData.SetValue(_NoInfoRow.ToString());

                tableDetailBlock.NoData.Show();
                tableDetailBlock.DetailRow.Hide();
                template.SetDetail.Append(tableDetailBlock);
            }
        }

        private void RenderTennisGameParlay(int maxRowNum, ResultTennis_Template template, Dictionary<int, TennisMatchStatistics> matchDetailDict, ref string awayTeamText, ref string homeTeamText, DataTable reportData)
        {
            int numberHideSet = 0;
            template.SetDetail.Clear();
            for (int rowNum = 0; rowNum < maxRowNum; rowNum++)
            {
                DataRow dr = reportData.Rows[rowNum];
                int matchId = Converter.ToInt(dr["matchid"]);
                int bettype = Converter.ToInt(dr["bettype"], -1);
                if (bettype != (int)BetType.SetXGameYWinner)
                {
                    numberHideSet++;
                    continue;
                }

                int game = 0;
                int line = 0;

                // Home and away team name
                this.BoldTeamByFinalScore(dr, ref homeTeamText, ref awayTeamText);

                if (matchDetailDict.ContainsKey(matchId))
                {
                    //Match detail dictionary by resource Id.
                    var resourceDict = matchDetailDict[matchId].SetDetailData;

                    var setIndex = string.Empty;
                    ResultTennis_SetDetail_TableDetail_Block tableDetailBlock = null;

                    for (int i = 1; i <= MAX_TENNIS_SET; i++)
                    {
                        tableDetailBlock = new Fanex.Age.UI.Reports.Result.ResultTennis_SetDetail_TableDetail_Block();
                        List<ResultTennis_SetDetail_TableDetail_DetailHeader_Block> detailHeaders = new List<ResultTennis_SetDetail_TableDetail_DetailHeader_Block>();
                        List<ResultTennis_SetDetail_TableDetail_DetailRow_Block> detailRows = new List<ResultTennis_SetDetail_TableDetail_DetailRow_Block>();

                        detailRows.Add(null);
                        detailHeaders.Add(null);

                        detailRows[0] = tableDetailBlock.DetailRow;
                        detailHeaders[0] = tableDetailBlock.DetailHeader;

                        game = 0;
                        line = 0;

                        //get max game num
                        var currentGameList = (from x in resourceDict where x.Key.StartsWith(string.Format("0{0}", i)) && x.Key.Length > 2 select x.Key).ToDictionary(x => x, null);
                        if (currentGameList.Count == 0)
                        {
                            continue;
                        }

                        int maxGame = Converter.ToInt(currentGameList.Keys.Max(), MAX_GAME_PER_RESULT_LINE) % 100;

                        detailHeaders[0].TitleNameBlock.Set_X_Game_Result = string.Format("Set {0} Game Result", i);
                        detailRows[0].HomeNameBlock.Home = homeTeamText;
                        detailRows[0].AwayNameBlock.Away = awayTeamText;

                        while (game < maxGame)
                        {
                            game++;
                            line = ((game - 1) / MAX_GAME_PER_RESULT_LINE) + 1;
                            setIndex = getSetIndex(i, game);

                            if (detailRows.Count < line)
                            {
                                detailRows.Add(new ResultTennis_SetDetail_TableDetail_DetailRow_Block());
                                detailHeaders.Add(new ResultTennis_SetDetail_TableDetail_DetailHeader_Block());

                                if (line < 3)
                                {
                                    detailRows[0].HomeNameBlock.Home += "</br>" + detailRows[0].AwayNameBlock.Away;
                                }

                                detailRows[0].AwayNameBlock.Hide();
                                detailRows[0].HomeNameBlock.mergeNum = (line * 3).ToString();

                                detailRows[line - 1].HomeNameBlock.Hide();
                                detailRows[line - 1].AwayNameBlock.Hide();
                                detailHeaders[line - 1].TitleNameBlock.Hide();
                            }

                            if (resourceDict.ContainsKey(setIndex))
                            {
                                var tennisSetDetail = resourceDict[setIndex];

                                if (line == 1) // <= 13 set
                                {
                                    setValueToDataRow(game, detailHeaders[0], detailRows[0], tennisSetDetail.HomeValue, tennisSetDetail.AwayValue, tennisSetDetail.SettlementStatusId);
                                }
                                else
                                {
                                    detailRows[line - 1].HomeNameBlock.Home = homeTeamText;
                                    detailRows[line - 1].AwayNameBlock.Away = awayTeamText;

                                    setValueToDataRow(game, detailHeaders[line - 1], detailRows[line - 1], tennisSetDetail.HomeValue, tennisSetDetail.AwayValue, tennisSetDetail.SettlementStatusId);
                                }
                            }
                            else
                            {
                                setValueToDataRow(game, detailHeaders[line - 1], detailRows[line - 1], " -", " -", (int)MatchSettlementStatus.Completed);
                            }
                        }

                        //change name of left column dont have data, game < 13
                        int endGame = (int)Math.Ceiling((double)game / MAX_GAME_PER_RESULT_LINE) * MAX_GAME_PER_RESULT_LINE;
                        while (game < endGame)
                        {
                            game++;
                            setValueToDataRow(game, detailHeaders[line - 1], detailRows[line - 1], " -", " -", (int)MatchSettlementStatus.Completed);
                        }

                        for (int subRowCount = 1; subRowCount <= detailRows.Count - 1; subRowCount++)
                        {
                            tableDetailBlock.DetailRow.Append(detailHeaders[subRowCount]);
                            tableDetailBlock.DetailRow.Append(detailRows[subRowCount]);
                        }

                        tableDetailBlock.NoData.Hide();

                        tableDetailBlock.WidthPercent = "100";
                        tableDetailBlock.MarginLeft = "0";
                        tableDetailBlock.MarginTop = "0";

                        template.SetDetail.Append(tableDetailBlock);
                    }

                    template.SetDetail.Show();
                }
            }
            if (numberHideSet == maxRowNum)
            {
                template.SetDetail.Hide();
            }
        }

        /// <summary>
        /// Get tennis set index string based on set and game input.
        /// </summary>
        /// <param name="set">Input set.</param>
        /// <param name="game">Input game.</param>
        /// <returns>Index string.</returns>
        private string getSetIndex(int set, int game)
        {
            return string.Format("0{0}{1}{2}", set, (game < 10) ? "0" : string.Empty, game);
        }

        /// <summary>
        /// Set tennis game value and header value to row block.
        /// </summary>
        /// <param name="order">Game order.</param>
        /// <param name="headerRow">Header Row Object to set data.</param>
        /// <param name="row">Row Object to set data.</param>
        /// <param name="homeValue">Home value.</param>
        /// <param name="awayValue">Away value.</param>
        /// <param name="settlementStatusId">Settlemen Status Id.</param>
        private void setValueToDataRow(int order, ResultTennis_SetDetail_TableDetail_DetailHeader_Block headerRow, ResultTennis_SetDetail_TableDetail_DetailRow_Block row, string homeValue, string awayValue, int settlementStatusId)
        {
            string matchValue = GetMatchValue((byte)settlementStatusId);

            if (string.IsNullOrEmpty(homeValue) || string.IsNullOrEmpty(awayValue))
            {
                homeValue = "-";
                awayValue = "-";
            }

            if (settlementStatusId == (int)MatchSettlementStatus.Refund || settlementStatusId == (int)MatchSettlementStatus.RefundHT || settlementStatusId == (int)MatchSettlementStatus.RefundFT)
            {
                homeValue = matchValue;
                awayValue = matchValue;
            }
            else if (settlementStatusId == (int)MatchSettlementStatus.Running)
            {
                homeValue = "-";
                awayValue = "-";
            }

            switch (order % MAX_GAME_PER_RESULT_LINE)
            {
                case 0:
                    {
                        headerRow.S13 = order.ToString();
                        row.HomeValueBlock.S13Home = homeValue;
                        row.AwayValueBlock.S13Away = awayValue;
                        break;
                    }
                case 1:
                    {
                        headerRow.S1 = order.ToString();
                        row.HomeValueBlock.S1Home = homeValue;
                        row.AwayValueBlock.S1Away = awayValue;
                        break;
                    }
                case 2:
                    {
                        headerRow.S2 = order.ToString();
                        row.HomeValueBlock.S2Home = homeValue;
                        row.AwayValueBlock.S2Away = awayValue;
                        break;
                    }
                case 3:
                    {
                        headerRow.S3 = order.ToString();
                        row.HomeValueBlock.S3Home = homeValue;
                        row.AwayValueBlock.S3Away = awayValue;
                        break;
                    }
                case 4:
                    {
                        headerRow.S4 = order.ToString();
                        row.HomeValueBlock.S4Home = homeValue;
                        row.AwayValueBlock.S4Away = awayValue;
                        break;
                    }
                case 5:
                    {
                        headerRow.S5 = order.ToString();
                        row.HomeValueBlock.S5Home = homeValue;
                        row.AwayValueBlock.S5Away = awayValue;
                        break;
                    }
                case 6:
                    {
                        headerRow.S6 = order.ToString();
                        row.HomeValueBlock.S6Home = homeValue;
                        row.AwayValueBlock.S6Away = awayValue;
                        break;
                    }
                case 7:
                    {
                        headerRow.S7 = order.ToString();
                        row.HomeValueBlock.S7Home = homeValue;
                        row.AwayValueBlock.S7Away = awayValue;
                        break;
                    }
                case 8:
                    {
                        headerRow.S8 = order.ToString();
                        row.HomeValueBlock.S8Home = homeValue;
                        row.AwayValueBlock.S8Away = awayValue;
                        break;
                    }
                case 9:
                    {
                        headerRow.S9 = order.ToString();
                        row.HomeValueBlock.S9Home = homeValue;
                        row.AwayValueBlock.S9Away = awayValue;
                        break;
                    }
                case 10:
                    {
                        headerRow.S10 = order.ToString();
                        row.HomeValueBlock.S10Home = homeValue;
                        row.AwayValueBlock.S10Away = awayValue;
                        break;
                    }
                case 11:
                    {
                        headerRow.S11 = order.ToString();
                        row.HomeValueBlock.S11Home = homeValue;
                        row.AwayValueBlock.S11Away = awayValue;
                        break;
                    }
                case 12:
                    {
                        headerRow.S12 = order.ToString();
                        row.HomeValueBlock.S12Home = homeValue;
                        row.AwayValueBlock.S12Away = awayValue;
                        break;
                    }
                default:
                    {
                        break;
                    }
            }
        }
