                    this.bettype = dr.Table.Columns.Contains("homeid2") ? Convert.ToInt32(dr["homeid2"]) : this.bettype;

                    if (currentLeagueId == 0 || currentLeagueId != leagueid)
                    {
                        if (this.bettype == (int)Sunplus.Agent.Model.BL.Definitions.BetType.Roulette || this.bettype == (int)Sunplus.Agent.Model.BL.Definitions.BetType.LiveRoulette)
                        {
