        private void RenderVirtualHorsesRacing(DataTable reportData, Result_ExcelContents_Block excelBlock)
        {
            // Get report rows
            var template = new Fanex.Age.UI.Reports.Result.ResultVirtualHorsesRacing_Template();
            var entities = EntityParser.ToEntities<VirtualHorsesRacingEntity>(reportData);
            template.Row.Clear();
            if (entities.Count > 0)
            {
                DateTime eventTime = DateTime.Now;
                int id = 0;
                foreach (var entity in entities)
                {
                    var rowBlock = new Fanex.Age.UI.Reports.Result.ResultVirtualHorsesRacing_Row_Block();
                    if (entity.EventStatus.ToLower().Equals("refund") && eventTime != entity.EventTime)
                    {
                        id++;
                        eventTime = entity.EventTime;

                        rowBlock.EventTime.rowspan = "1";
                        rowBlock.EventTime.EventTime = Formater.FullDateFormat2Line(entity.EventTime);
                        rowBlock.ColorClass = (id + 1) % 2 == 0 ? EVEN_ROW_CLASS : ODD_ROW_CLASS;
                        rowBlock.Placing = "N/A";
                        rowBlock.HorseNo = "N/A";
                        rowBlock.Result = "N/A";
                        rowBlock.Win = "N/A";
                        rowBlock.Place = "N/A";
                        rowBlock.Status = "Refund";
                        template.Row.Append(rowBlock);
                    }

                    if (entity.Place == 0)
                    {
                        continue;
                    }

                    if (entity == entities.First() || eventTime != entity.EventTime)
                    {
                        id++;
                        eventTime = entity.EventTime;
                        rowBlock.EventTime.rowspan = entities.Where(x => x.EventTime == eventTime && x.Place != 0).Count().ToString();
                        rowBlock.EventTime.EventTime = Formater.FullDateFormat2Line(entity.EventTime);
                    }
                    else
                    {
                        rowBlock.EventTime.Hide();
                    }

                    rowBlock.ColorClass = (id + 1) % 2 == 0 ? EVEN_ROW_CLASS : ODD_ROW_CLASS;
                    rowBlock.Placing = GetHorseRacingPlaceString(entity.Place.ToString());
                    rowBlock.HorseNo = entity.HorseNo.ToString();
                    rowBlock.Result = CacheRef.GetHorseTeamName(entity.HorseId);
                    rowBlock.Win = Formater.FormatNumber20(entity.WinOdds, CurrentUserSession.LangKey);
