        // Define list key for eventstatus
        static Dictionary<string, int> _event = new Dictionary<string, int>()
            {
                { "running", Convert.ToInt32("0000000", 2) },
                { "completed", Convert.ToInt32("0000001", 2) },
                { "closed", Convert.ToInt32("0000010", 2) },
                { "postponed", Convert.ToInt32("0000011", 2) },
                { "refund", Convert.ToInt32("0000100", 2) },
                { "refund ft", Convert.ToInt32("0000101", 2) },
                { "refund ht", Convert.ToInt32("0000110", 2) },
                { "won", Convert.ToInt32("0000111", 2) },
                { "internal", Convert.ToInt32("0001000", 2) }
            };

        // Define list key for Result: isPending(1 bit) isHTCal(1 bit) calculate(1 bit) enventStatus(4 bit)
        static Dictionary<int, string> _result = new Dictionary<int, string>()
            {
                { Convert.ToInt32("0000010", 2), "closed" },
                { Convert.ToInt32("0100010", 2), "closed" },
                { Convert.ToInt32("0000000", 2), "running" },
                { Convert.ToInt32("0100000", 2), "running" },
                { Convert.ToInt32("1000000", 2), "pending" },
                { Convert.ToInt32("1010010", 2), "pending" },
                { Convert.ToInt32("1100010", 2), "pending" },
                { Convert.ToInt32("1100000", 2), "pending" },
                { Convert.ToInt32("1010000", 2), "pending" },
                { Convert.ToInt32("0110001", 2), "completed" },
                { Convert.ToInt32("1000010", 2), "pending" },
                { Convert.ToInt32("0000100", 2), "refund" },
                { Convert.ToInt32("0000101", 2), "refundft" },
                { Convert.ToInt32("0010101", 2), "refundft" },
                { Convert.ToInt32("0010110", 2), "refundht" },
                { Convert.ToInt32("0000110", 2), "refundht" },
                { Convert.ToInt32("0010111", 2), "lblWon" },
                { Convert.ToInt32("0000111", 2), "lblWon" },
                { Convert.ToInt32("0010011", 2), "postponed" },
                { Convert.ToInt32("0000011", 2), "postponed" },
                { Convert.ToInt32("0011000", 2), "Internal" },
                { Convert.ToInt32("0001000", 2), "Internal" },
            };

        /// <summary>
        /// Map event status to coresponding language
        /// </summary>
        /// <param name="eventstatus"></param>
        /// <param name="isPending"></param>
        /// <param name="isHTcal"></param>
        /// <param name="calculate"></param>
        /// <returns></returns>
        protected string MapEventStatusString(string eventstatus, bool isPending, bool isHTcal, bool calculate)
        {
            int resultKey = 0x0000000;
            int pending = Convert.ToInt32(isPending);
            int htCal = Convert.ToInt32(isHTcal);
            int cal = Convert.ToInt32(calculate);

            pending <<= 6; // Shift right 6 bit for pending status
            htCal <<= 5; // Shift right 5 bit for haft time calculate status
            cal <<= 4; // Shift right 4 bit for calculate status

            resultKey = pending | htCal | cal;

            if (_event.ContainsKey(eventstatus.ToLowerInvariant()))
            {
                resultKey |= _event[eventstatus.ToLowerInvariant()]; // Or with event status
                if (_result.ContainsKey(resultKey))
                {
                    return this.GetLogResource(_result[resultKey]);
                }
                else
                {
                    // Get status from resource lang, if have.
                    string str = this.GetLogResource(eventstatus);
                    if (str != string.Empty)
                    {
                        return this.GetLogResource(eventstatus.ToLower());
                    }
                }
            }

            return this.UppercaseFirst(eventstatus);
        }

        static object locker = new object();
        static ResourceManager _resourceManager = null;

        public string GetLogResource(string key)
        {
            if (_resourceManager == null)
            {
                lock (locker)
                {
                    if (_resourceManager == null)
                    {
                        _resourceManager = new ResourceManager(typeof(Resources.Lang));
                        _resourceManager.IgnoreCase = true;
                    }
                }
            }

            return _resourceManager.GetString(key) ?? string.Empty;
        }

        public ResourceManager GetLangResourceManager()
        {
            if (_resourceManager == null)
            {
                lock (locker)
                {
                    if (_resourceManager == null)
                    {
                        _resourceManager = new ResourceManager(typeof(Resources.Lang));
                        _resourceManager.IgnoreCase = true;
                    }
                }
            }

            return _resourceManager;
        }

        private string UppercaseFirst(string s)
        {
            if (string.IsNullOrEmpty(s))
            {
                return string.Empty;
            }

            char[] a = s.ToCharArray();
            a[0] = char.ToUpper(a[0]);
            return new string(a);
        }

        #endregion Map event status to coresponding language

        private string FormatDateTimeNotSecond(object datetime)
        {
            var result = string.Empty;
            if (Convert.IsDBNull(datetime) || datetime == null)
            {
                return string.Empty;
            }

            result = Converter.ToDateTime(datetime).ToString("MM/dd/yyyy<br/>hh:mm tt");

            return result;
        }

        private DataTable makeMatchDetailDataTable()
        {
            DataTable table = new DataTable();

            table.Columns.Add("MatchId", typeof(int));
            table.Columns.Add("SetHomeArr", typeof(string[]));
            table.Columns.Add("SetAwayArr", typeof(string[]));
            table.Columns.Add("TotalGameH", typeof(string));
            table.Columns.Add("TotalGameA", typeof(string));
            table.Columns.Add("TotalSetH", typeof(string));
            table.Columns.Add("TotalSetA", typeof(string));
            table.Columns.Add("Status", typeof(string));
            table.Columns.Add("StatusValue", typeof(int));
            table.Columns.Add("StatusDetail", typeof(bool));
            table.Columns.Add("SetDetailData", typeof(object));

            return table;
        }


        private string GetMatchValue(byte SettlementStatusId)
        {
            if (SettlementStatusId == 0)
            {
                return GetLogResource("running");
            }
            else if (SettlementStatusId == 1)
            {
                return GetLogResource("refund");
            }
            else if (SettlementStatusId == 2)
            {
                return GetLogResource("refundht");
            }
            else if (SettlementStatusId == 3)
            {
                return GetLogResource("refundft");
            }
            else if (SettlementStatusId == 4)
            {
                return GetLogResource("completed");
            }
            else
            {
                return "-";
            }
        }

        private DataTable CalculateTennisResult(DataTable detailTable)
        {
            List<TennisMatchDetail> matchDetailList = null;
            if (this._matchId > 0) //Age_BetList_SelMatchResult, Age_BetList_SelMatchResultParlay, Age_Result_MatchSelResultDetail
            {
                matchDetailList = detailTable.AsEnumerable().Select(x => new TennisMatchDetail(x.Field<int>(0), x.Field<string>(1), x.Field<string>(2), x.Field<string>(3), x.Field<byte>(5))).ToList();
            }
            else // Age_Result_MatchSelByLeague
            {
                matchDetailList = detailTable.AsEnumerable().Select(x => new TennisMatchDetail(x.Field<int>(0), x.Field<string>(1), x.Field<string>(2), x.Field<string>(3), x.Field<byte>(4))).ToList();
            }

            if (matchDetailList == null)
            {
                matchDetailList = new List<TennisMatchDetail>();
            }

            var matchDetailDict = matchDetailList.GroupBy(x => x.MatchId).ToDictionary(x => x.Key, x => x.ToList());

            //Match detail dictionary by resource Id.
            Dictionary<string, TennisMatchDetail> resourceDict = null;

            string matchValue = string.Empty;

            DataTable matchStatDataTable = makeMatchDetailDataTable();
            foreach (var match in matchDetailDict)
            {
                resourceDict = match.Value.ToDictionary(x => x.ResourceId, x => new TennisMatchDetail(0, x.ResourceId, x.HomeValue, x.AwayValue, x.SettlementStatusId));

                TennisMatchStatistics matchStatistics = new TennisMatchStatistics();
                matchStatistics.MatchId = match.Key;
                bool isNoTotalRow = false;
                bool isAtLeastRefund = false;
                bool isAtLeastSettle = false;
                int TotalGameHome = 0;
                int TotalGameAway = 0;
                bool isDetail = false;
                string matchIndex = string.Empty;

                //follow to this mockup: redmine.nexcel.vn/projects/sporting-solution/wiki/P2_2_Bet_List_Core#2IB > Changes on Result
                //// Individual set
                for (int i = 1; i <= MAX_TENNIS_SET; i++)
                {
                    matchIndex = "0" + i.ToString();
                    if (!isDetail)
                    {
                        isDetail = (from x in resourceDict where x.Key.StartsWith(string.Format("0{0}", i)) && x.Key.Length > 2 select x.Key).ToList().Count > 0;
                    }

                    if (resourceDict.ContainsKey(matchIndex))
                    {
                        if (!isAtLeastSettle)
                        {
                            isAtLeastSettle = true;
                        }

                        if (resourceDict[matchIndex].SettlementStatusId == (int)MatchSettlementStatus.Completed)
                        {
                            matchStatistics.SetHomeArr[i - 1] = resourceDict[matchIndex].HomeValue;
                            matchStatistics.SetAwayArr[i - 1] = resourceDict[matchIndex].AwayValue;

                            TotalGameHome += Converter.ToInt(resourceDict[matchIndex].HomeValue);
                            TotalGameAway += Converter.ToInt(resourceDict[matchIndex].AwayValue);
                        }

                        else if (resourceDict[matchIndex].SettlementStatusId == (int)MatchSettlementStatus.Refund || resourceDict[matchIndex].SettlementStatusId == (int)MatchSettlementStatus.RefundHT || resourceDict[matchIndex].SettlementStatusId == (int)MatchSettlementStatus.RefundFT)
                        {
                            if (!isAtLeastRefund)
                            {
                                isAtLeastRefund = true;
                            }

                            matchValue = GetMatchValue(resourceDict[matchIndex].SettlementStatusId);
                            matchStatistics.SetHomeArr[i - 1] = matchValue;
                            matchStatistics.SetAwayArr[i - 1] = matchValue;
                        }
                        else if (resourceDict[matchIndex].SettlementStatusId == (int)MatchSettlementStatus.Running)
                        {
                            matchValue = GetMatchValue(resourceDict[matchIndex].SettlementStatusId);
                            matchStatistics.SetHomeArr[i - 1] = "-";
                            matchStatistics.SetAwayArr[i - 1] = "-";
                        }
                    }
                    else
                    {
                        matchStatistics.SetHomeArr[i - 1] = "-";
                        matchStatistics.SetAwayArr[i - 1] = "-";
                    }
                }

                ////Total Sets
                matchIndex = "00";
                if (resourceDict.ContainsKey(matchIndex))
                {
                    matchStatistics.StatusValue = resourceDict[matchIndex].SettlementStatusId;
                    matchValue = GetMatchValue(resourceDict[matchIndex].SettlementStatusId);

                    if (resourceDict[matchIndex].SettlementStatusId == (int)MatchSettlementStatus.Completed)
                    {
                        matchStatistics.TotalSetHome = resourceDict[matchIndex].HomeValue;
                        matchStatistics.TotalSetAway = resourceDict[matchIndex].AwayValue;
                    }
                    else if (resourceDict[matchIndex].SettlementStatusId == (int)MatchSettlementStatus.Running)
                    {
                        matchStatistics.TotalSetHome = "-";
                        matchStatistics.TotalSetAway = "-";
                    }
                    else if (resourceDict[matchIndex].SettlementStatusId == (int)MatchSettlementStatus.Refund || resourceDict[matchIndex].SettlementStatusId == (int)MatchSettlementStatus.RefundHT || resourceDict[matchIndex].SettlementStatusId == (int)MatchSettlementStatus.RefundFT)
                    {
                        matchStatistics.TotalSetHome = matchValue;
                        matchStatistics.TotalSetAway = matchValue;
                    }

                    matchStatistics.Status = matchValue;
                }
                else
                {
                    matchStatistics.StatusValue = (int)MatchSettlementStatus.Completed;

                    matchStatistics.TotalSetHome = "-";
                    matchStatistics.TotalSetAway = "-";

                    matchStatistics.Status = string.Empty;
                    isNoTotalRow = true;
                }

                ////Total Games
                if (isNoTotalRow)
                {
                    matchStatistics.TotalGameHome = "-";
                    matchStatistics.TotalGameAway = "-";
                }
                else if (matchStatistics.StatusValue == (int)MatchSettlementStatus.Completed)
                {
                    matchStatistics.TotalGameHome = TotalGameHome.ToString();
                    matchStatistics.TotalGameAway = TotalGameAway.ToString();
                }
                else if (matchStatistics.StatusValue == (int)MatchSettlementStatus.Running)
                {
                    matchStatistics.TotalGameHome = "-";
                    matchStatistics.TotalGameAway = "-";
                }
                else if (matchStatistics.StatusValue == (int)MatchSettlementStatus.Refund || matchStatistics.StatusValue == (int)MatchSettlementStatus.RefundHT || matchStatistics.StatusValue == (int)MatchSettlementStatus.RefundFT)
                {
                    matchStatistics.TotalGameHome = matchStatistics.TotalSetHome;
                    matchStatistics.TotalGameAway = matchStatistics.TotalSetAway;
                }

                //Status
                matchStatistics.StatusDetail = isDetail;
                matchStatDataTable.Rows.Add(match.Key, matchStatistics.SetHomeArr, matchStatistics.SetAwayArr, matchStatistics.TotalGameHome, matchStatistics.TotalGameAway, matchStatistics.TotalSetHome, matchStatistics.TotalSetAway, matchStatistics.Status, matchStatistics.StatusValue, matchStatistics.StatusDetail, resourceDict);
            }

            return matchStatDataTable;
        }
    }
